public class CategoryPlot_getDomainAxisIndex_TriageGen0Test {

    private CategoryPlot plot;
    private CategoryDataset dataset;
    private CategoryAxis axis1;
    private CategoryAxis axis2;
    private ValueAxis rangeAxis;
    private CategoryItemRenderer renderer;

    @Before
    public void setUp() {
        dataset = Mockito.mock(CategoryDataset.class);
        axis1 = Mockito.mock(CategoryAxis.class);
        axis2 = Mockito.mock(CategoryAxis.class);
        rangeAxis = Mockito.mock(ValueAxis.class);
        renderer = Mockito.mock(CategoryItemRenderer.class);
        plot = new CategoryPlot(dataset, axis1, rangeAxis, renderer);
    }

    @Test
    public void testGetDomainAxisIndex_ExistingAxisFirst() {
        // axis1 is at index 0
        int index = plot.getDomainAxisIndex(axis1);
        assertEquals("The index of the first axis should be 0", 0, index);
    }

    @Test
    public void testGetDomainAxisIndex_ExistingAxisSecond() {
        // Adding a second axis
        plot.setDomainAxis(1, axis2);

        int index = plot.getDomainAxisIndex(axis2);
        assertEquals("The index of the second axis should be 1", 1, index);
    }

    @Test
    public void testGetDomainAxisIndex_NonExistingAxis() {
        CategoryAxis unknownAxis = Mockito.mock(CategoryAxis.class);
        int index = plot.getDomainAxisIndex(unknownAxis);
        assertEquals("The index of an axis not in the list should be -1", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_EmptyAxes() {
        plot.clearDomainAxes();
        int index = plot.getDomainAxisIndex(axis1);
        assertEquals("The index in an empty plot should be -1", -1, index);
    }

    @Test
    public void testGetDomainAxisIndex_MultipleAxes() {
        CategoryAxis axis3 = Mockito.mock(CategoryAxis.class);
        plot.setDomainAxis(1, axis2);
        plot.setDomainAxis(2, axis3);

        assertEquals(0, plot.getDomainAxisIndex(axis1));
        assertEquals(1, plot.getDomainAxisIndex(axis2));
        assertEquals(2, plot.getDomainAxisIndex(axis3));
    }
}
